create table if not exists supply_automation_events (id bigint generated always as identity primary key,business_id uuid not null references businesses(id) on delete cascade,event_type text not null,source_type text not null,source_id uuid not null,payload jsonb not null default '{}'::jsonb,event_hash text not null check(length(event_hash)=64),created_at timestamptz not null default now(),unique(business_id,event_type,source_type,source_id));
create table if not exists supply_automation_runs (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,event_id bigint not null references supply_automation_events(id) on delete restrict,status text not null default 'queued' check(status in ('queued','running','completed','failed','cancelled')),action_id uuid references supply_recovery_actions(id) on delete restrict,error_code text,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(event_id));
create index if not exists idx_v25_events_business on supply_automation_events(business_id,created_at desc);
create index if not exists idx_v25_runs_business on supply_automation_runs(business_id,status,created_at desc);
alter table supply_automation_events enable row level security;
alter table supply_automation_runs enable row level security;
create policy v25_events_select on supply_automation_events for select using(is_member(business_id));
create policy v25_runs_select on supply_automation_runs for select using(is_member(business_id));
create or replace function public.v25_hash_automation_event(p_business_id uuid,p_event_type text,p_source_type text,p_source_id uuid,p_payload jsonb) returns text language sql immutable as $$ select encode(digest(concat_ws('|',p_business_id::text,p_event_type,p_source_type,p_source_id::text,p_payload::text),'sha256'),'hex') $$;
create or replace function public.v25_emit_automation_event(p_business_id uuid,p_event_type text,p_source_type text,p_source_id uuid,p_payload jsonb) returns bigint language plpgsql security definer set search_path=public as $$ declare x bigint; h text; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_payload is null then raise exception 'Automation payload required'; end if; h:=v25_hash_automation_event(p_business_id,p_event_type,p_source_type,p_source_id,p_payload); perform pg_advisory_xact_lock(hashtextextended('NABUUMA|AUTOMATION_EVENTS|V2.5',0)); select id into x from supply_automation_events where business_id=p_business_id and event_type=p_event_type and source_type=p_source_type and source_id=p_source_id for update; if x is not null then return x; end if; insert into supply_automation_events(business_id,event_type,source_type,source_id,payload,event_hash) values(p_business_id,p_event_type,p_source_type,p_source_id,p_payload,h) returning id into x; return x; end; $$;
create or replace function public.v25_queue_automation_run(p_business_id uuid,p_event_id bigint) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if not exists(select 1 from supply_automation_events where id=p_event_id and business_id=p_business_id) then raise exception 'Automation event not found'; end if; perform pg_advisory_xact_lock(hashtextextended('NABUUMA|AUTOMATION_RUNS|V2.5',0)); select id into x from supply_automation_runs where event_id=p_event_id for update; if x is not null then return x; end if; insert into supply_automation_runs(business_id,event_id) values(p_business_id,p_event_id) returning id into x; return x; end; $$;
revoke all on function public.v25_hash_automation_event(uuid,text,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.v25_hash_automation_event(uuid,text,text,uuid,jsonb) to authenticated;
revoke all on function public.v25_emit_automation_event(uuid,text,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.v25_emit_automation_event(uuid,text,text,uuid,jsonb) to authenticated;
revoke all on function public.v25_queue_automation_run(uuid,bigint) from public,anon,authenticated;
grant execute on function public.v25_queue_automation_run(uuid,bigint) to authenticated;